// `setup-sql.ps1`: the one-time SQL Server preparation for arashouse (ticket 22), generated by
// `arashouse setup-sql` from the same constants as the guards (names.ts, flavors.ts) and run once by a
// SQL Server `sysadmin`: the captain's Windows login, since `sa` is rejected on this host (ticket 09).
// It creates the utility database `arashouse_admin`, its seven name-checked procedures, the broker's
// login (which is in no server role) and the two certificates that carry the procedures' server rights.
// Pure: this module only builds text. docs/setup-sql.md describes the objects; setup-sql.test.ts checks
// the text and test/setup-sql.test.ts parses the script under Windows PowerShell.

import { FLAVOR_KEYS } from "./flavors.js";
import { assertValidRoot } from "./guards.js";
import {
  DEFAULT_INSTALL_ROOT,
  MAX_SLOT,
  UTILITY_DATABASE,
  databaseFiles,
  databaseName,
  loginName,
  sqlDataDir,
  stagingDir,
  type LoginRole,
  type SlotRef,
} from "./names.js";
import type { HostInfo } from "../host/driver.js";
import { STAGED_BACKUP_NAME, stagedBackup } from "./restore.js";
import { psQuote, serviceAccount, type SetupFinding } from "./setup-host.js";

/** The broker's SQL login: its Windows account, by Windows authentication, so no SQL password exists for it. */
export const POOL_LOGIN = serviceAccount();

/** The pool login's user in `arashouse_admin`; it may execute the procedures and nothing else. */
export const POOL_USER = "arashouse_pool";

/**
 * The certificate the procedures are signed with, and the login made from it in `master`. Nobody can
 * log in as a certificate login; its server rights reach only code signed with the certificate, and the
 * private key is removed once the procedures are signed, so no new code can be.
 */
export const SIGNER = "arashouse_admin_signer";

/** What the signer login holds, so that the procedures can do their jobs for a caller that holds none of it. */
export const SIGNER_PERMISSIONS = ["CREATE ANY DATABASE", "ALTER ANY CONNECTION", "ALTER ANY LOGIN", "VIEW SERVER STATE"] as const;

/**
 * The second certificate (ticket 39), made and stripped of its private key the same way, signing `adopt_slot_database`
 * alone. A database restored from a leaseholder's backup keeps the backup's `dbo` inside, and the broker, its owner in
 * `sys.databases`, then cannot open it; `ALTER AUTHORIZATION` back to the broker needs `TAKE OWNERSHIP` on a database
 * nobody can open, which only `CONTROL SERVER` covers (measured on LocalDB, 2026-10-28: `ALTER ANY DATABASE` is not
 * enough). So that right sits on a certificate of its own, reachable only through that one procedure.
 */
export const ADOPTER = "arashouse_admin_adopter";

/** What the adopter login holds. */
export const ADOPTER_PERMISSIONS = ["CONTROL SERVER"] as const;

/** The procedures in `arashouse_admin.dbo`, in the order the script creates them. */
export const ADMIN_PROCEDURES = [
  "create_slot_database",
  "drop_slot_database",
  "kill_connections",
  "create_slot_login",
  "drop_slot_login",
  "read_staged_backup",
  "adopt_slot_database",
] as const;
export type AdminProcedure = (typeof ADMIN_PROCEDURES)[number];

/** The certificates, each with the rights its login holds and the procedures it signs, in the order the script makes them. */
export const SIGNERS: readonly { readonly name: string; readonly permissions: readonly string[]; readonly procedures: readonly AdminProcedure[] }[] = [
  { name: SIGNER, permissions: SIGNER_PERMISSIONS, procedures: ADMIN_PROCEDURES.filter((p) => p !== "adopt_slot_database") },
  { name: ADOPTER, permissions: ADOPTER_PERMISSIONS, procedures: ["adopt_slot_database"] },
];

/** The certificate that signs `procedure`. */
export function signerOf(procedure: AdminProcedure): string {
  return SIGNERS.find((s) => s.procedures.includes(procedure))!.name;
}

/** The ticket that added each procedure, for its header comment. */
const PROCEDURE_TICKET: Readonly<Record<AdminProcedure, string>> = {
  create_slot_database: "22",
  drop_slot_database: "22",
  kill_connections: "22",
  create_slot_login: "22",
  drop_slot_login: "22",
  read_staged_backup: "39",
  adopt_slot_database: "39",
};

/** The errors the procedures raise (`THROW`). */
export const SQL_ERRORS = {
  /** The name is not a slot database or slot login name. */
  refusedName: 50001,
  /** The database or login exists and is not the pool's (another owner, a role member, not a SQL login). */
  notOwned: 50002,
  /** The database does not exist. */
  missing: 50003,
  /** The pool login does not exist. */
  noPoolLogin: 50004,
  /** A slot login's password is missing or shorter than 16 characters. */
  badPassword: 50005,
} as const;

/** The slot the `-SelfTest` round trip creates and drops: the last flavor's slot 99, which no pool uses. */
export const SELF_TEST_SLOT: SlotRef = { flavor: FLAVOR_KEYS[FLAVOR_KEYS.length - 1] as SlotRef["flavor"], slot: MAX_SLOT };

/** A name no flavor, slot or login of the tool ever has: the target of the direct negative test. */
export const NEGATIVE_DATABASE = "arashouse_negative_madeup";

/** A T-SQL Unicode string literal. */
export function sqlString(text: string): string {
  return `N'${text.replace(/'/g, "''")}'`;
}

/** A T-SQL bracketed identifier. */
function sqlName(name: string): string {
  return `[${name.replace(/]/g, "]]")}]`;
}

/**
 * The binary-collation LIKE pattern that matches `name` with its slot number replaced by any two
 * digits: `arashouse_23_77_dbo` gives `arashouse[_]23[_][0-9][0-9][_]dbo`.
 */
function slotPattern(name: string): string {
  const escaped = name.replace(/_/g, "[_]");
  if (escaped.split("[_]77").length !== 2) throw new Error(`"${name}" does not hold the slot number 77 exactly once`);
  return escaped.replace("[_]77", "[_][0-9][0-9]");
}

/** One pattern per flavor for a slot database (`arashouse_<key>_<NN>`), derived from names.ts. */
export function databasePatterns(): string[] {
  return FLAVOR_KEYS.map((flavor) => slotPattern(databaseName({ flavor, slot: 77 })));
}

/** One pattern per flavor and role for a slot login (`arashouse_<key>_<NN>_dbo` or `_reg`), derived from names.ts. */
export function loginPatterns(): string[] {
  const roles: LoginRole[] = ["dbo", "reg"];
  return FLAVOR_KEYS.flatMap((flavor) => roles.map((role) => slotPattern(loginName({ flavor, slot: 77 }, role))));
}

/**
 * The allowlist every procedure runs first: `variable` must be one of `patterns` exactly, compared in a
 * binary collation (so only ASCII digits and lower case match), with no trailing space (which LIKE would
 * ignore) and not slot `00`. Anything else is refused before the procedure reads or builds anything.
 */
function allowlistCheck(variable: string, patterns: readonly string[], zeroSlot: string, what: string): string {
  const bin = `${variable} COLLATE Latin1_General_BIN2`;
  return [
    `    IF ${variable} IS NULL`,
    `        OR DATALENGTH(${variable}) <> 2 * LEN(${variable})`,
    `        OR NOT (`,
    patterns.map((p, i) => `            ${i === 0 ? "" : "OR "}${bin} LIKE N'${p}'`).join("\n"),
    `        )`,
    `        OR ${bin} LIKE N'${zeroSlot}'`,
    `    BEGIN`,
    `        THROW ${SQL_ERRORS.refusedName}, ${sqlString(`arashouse_admin: refused: not ${what}`)}, 1;`,
    `    END;`,
  ].join("\n");
}

const databaseCheck = (): string => allowlistCheck("@database", databasePatterns(), "%[_]00", "an arashouse slot database name");
const loginCheck = (): string => allowlistCheck("@login", loginPatterns(), "%[_]00[_]___", "an arashouse slot login name");

/** Refuses when `@database` exists and the pool login does not own it. Expects `@pool` declared. */
const ownerCheck = (): string =>
  [
    `    IF NOT EXISTS (SELECT 1 FROM sys.databases WHERE database_id = DB_ID(@database) AND owner_sid = @pool)`,
    `    BEGIN`,
    `        THROW ${SQL_ERRORS.notOwned}, ${sqlString("arashouse_admin: refused: the database is not owned by the pool login")}, 1;`,
    `    END;`,
  ].join("\n");

const poolSid = (): string =>
  [
    `    DECLARE @pool varbinary(85) = SUSER_SID(${sqlString(POOL_LOGIN)});`,
    `    IF @pool IS NULL OR NOT EXISTS (SELECT 1 FROM sys.server_principals WHERE sid = @pool)`,
    `    BEGIN`,
    `        THROW ${SQL_ERRORS.noPoolLogin}, ${sqlString("arashouse_admin: the pool login does not exist")}, 1;`,
    `    END;`,
  ].join("\n");

/** Refuses when `@login` exists and is not a plain SQL login outside every server role. */
const slotLoginCheck = (): string =>
  [
    `    IF EXISTS (SELECT 1 FROM sys.server_principals WHERE name = @login AND type <> 'S')`,
    `        OR EXISTS (SELECT 1 FROM sys.server_role_members m JOIN sys.server_principals p ON p.principal_id = m.member_principal_id WHERE p.name = @login)`,
    `    BEGIN`,
    `        THROW ${SQL_ERRORS.notOwned}, ${sqlString("arashouse_admin: refused: the login is not a plain SQL login outside every server role")}, 1;`,
    `    END;`,
  ].join("\n");

/**
 * Ends every user session in `sessions` (a query of `session_id`s) except the caller's own, counting
 * them in `@killed`. A session that ended meanwhile (6106) is not an error.
 */
function killSessions(sessions: string): string {
  return [
    `    DECLARE @spid int, @kill nvarchar(64);`,
    `    DECLARE victims CURSOR LOCAL FAST_FORWARD FOR`,
    `        SELECT s.session_id FROM sys.dm_exec_sessions AS s`,
    `        WHERE s.is_user_process = 1 AND s.session_id <> @@SPID AND s.session_id IN (${sessions});`,
    `    OPEN victims;`,
    `    FETCH NEXT FROM victims INTO @spid;`,
    `    WHILE @@FETCH_STATUS = 0`,
    `    BEGIN`,
    `        SET @kill = N'KILL ' + CAST(@spid AS nvarchar(11)) + N';';`,
    `        BEGIN TRY`,
    `            EXEC (@kill);`,
    `            SET @killed += 1;`,
    `        END TRY`,
    `        BEGIN CATCH`,
    `            IF ERROR_NUMBER() <> 6106`,
    `            BEGIN`,
    `                THROW;`,
    `            END;`,
    `        END CATCH;`,
    `        FETCH NEXT FROM victims INTO @spid;`,
    `    END;`,
    `    CLOSE victims;`,
    `    DEALLOCATE victims;`,
  ].join("\n");
}

/** Sessions using `@database`: those whose current database it is, and those holding a lock on it. */
const DATABASE_SESSIONS =
  "SELECT database_sessions.session_id FROM sys.dm_exec_sessions AS database_sessions WHERE database_sessions.database_id = DB_ID(@database) " +
  "UNION SELECT locks.request_session_id FROM sys.dm_tran_locks AS locks WHERE locks.resource_type = N'DATABASE' AND locks.resource_database_id = DB_ID(@database)";

/** Sessions of `@login`. */
const LOGIN_SESSIONS = "SELECT login_sessions.session_id FROM sys.dm_exec_sessions AS login_sessions WHERE login_sessions.security_id = SUSER_SID(@login)";

function procedure(name: AdminProcedure, params: string, purpose: string, body: string[]): string {
  return [
    `CREATE PROCEDURE dbo.${name} ${params}`,
    `AS`,
    `BEGIN`,
    `    -- arashouse ticket ${PROCEDURE_TICKET[name]}, generated by \`arashouse setup-sql\` (docs/setup-sql.md); signed with ${signerOf(name)}. Do not edit.`,
    `    -- ${purpose}`,
    `    SET NOCOUNT ON;`,
    `    SET XACT_ABORT ON;`,
    ...body,
    `END`,
  ].join("\n");
}

/** A T-SQL LIKE pattern matching `text` literally. */
function likeLiteral(text: string): string {
  return text.replace(/[[\]%_]/g, (c) => `[${c}]`);
}

/**
 * The one path `read_staged_backup` reads: `<root>\staging\<lease_id>\restore.bak` (`stagedBackup` in restore.ts),
 * as a binary-collation LIKE pattern: the lease id is 32 lower-case hex digits and nothing else varies.
 */
export function stagedBackupPattern(root: string = DEFAULT_INSTALL_ROOT): string {
  const sample = stagedBackup("0".repeat(32), root);
  const prefix = stagingDir("0".repeat(32), root).slice(0, -32);
  if (sample !== `${prefix}${"0".repeat(32)}\\${STAGED_BACKUP_NAME}`) throw new Error("the staged backup path has drifted from stagedBackup()");
  return `${likeLiteral(prefix)}${"[0-9a-f]".repeat(32)}${likeLiteral(`\\${STAGED_BACKUP_NAME}`)}`;
}

/**
 * The seven procedures' `CREATE PROCEDURE` text, generated from names.ts. Each checks its name (or path)
 * against the allowlist before anything else, builds dynamic SQL only from a checked name (through `QUOTENAME`)
 * or from that name inside a fixed path under `<root>\sqldata\`, and acts only on a database the pool
 * login owns or a plain SQL login of a slot's name.
 */
export function renderAdminProcedures(root: string = DEFAULT_INSTALL_ROOT): Record<AdminProcedure, string> {
  const vetted = assertValidRoot(root);
  const dataDir = sqlDataDir(vetted);
  const sample = databaseFiles(databaseName(SELF_TEST_SLOT), vetted);
  if (sample.data !== `${dataDir}\\${databaseName(SELF_TEST_SLOT)}.mdf` || sample.log !== `${dataDir}\\${databaseName(SELF_TEST_SLOT)}_log.ldf`) {
    throw new Error("the procedures' file names have drifted from databaseFiles()");
  }
  const dataPrefix = sqlString(`${dataDir}\\`);
  return {
    create_slot_database: procedure("create_slot_database", "@database nvarchar(128)", "Creates an empty slot database (AUTO_CLOSE off) owned by the pool login (1), or does nothing when the pool already owns it (0).", [
      databaseCheck(),
      poolSid(),
      `    IF DB_ID(@database) IS NOT NULL`,
      `    BEGIN`,
      ownerCheck().replace(/^ {4}/gm, "        "),
      `        RETURN 0;`,
      `    END;`,
      `    DECLARE @data nvarchar(260) = ${dataPrefix} + @database + N'.mdf';`,
      `    DECLARE @log nvarchar(260) = ${dataPrefix} + @database + N'_log.ldf';`,
      `    DECLARE @sql nvarchar(max) = N'CREATE DATABASE ' + QUOTENAME(@database)`,
      `        + N' ON PRIMARY (NAME = ' + QUOTENAME(@database + N'_data') + N', FILENAME = N''' + @data + N''')'`,
      `        + N' LOG ON (NAME = ' + QUOTENAME(@database + N'_log') + N', FILENAME = N''' + @log + N''');';`,
      `    EXEC (@sql);`,
      `    SET @sql = N'ALTER DATABASE ' + QUOTENAME(@database) + N' SET AUTO_CLOSE OFF;';`,
      `    EXEC (@sql);`,
      `    IF NOT EXISTS (SELECT 1 FROM sys.databases WHERE database_id = DB_ID(@database) AND owner_sid = @pool)`,
      `    BEGIN`,
      `        SET @sql = N'ALTER AUTHORIZATION ON DATABASE::' + QUOTENAME(@database) + N' TO ' + QUOTENAME(${sqlString(POOL_LOGIN)}) + N';';`,
      `        EXEC (@sql);`,
      `    END;`,
      `    RETURN 1;`,
    ]),
    drop_slot_database: procedure("drop_slot_database", "@database nvarchar(128)", "Ends the sessions in a slot database the pool login owns and drops it (1), or does nothing when it does not exist (0).", [
      databaseCheck(),
      poolSid(),
      `    IF DB_ID(@database) IS NULL RETURN 0;`,
      ownerCheck(),
      `    DECLARE @killed int = 0;`,
      killSessions(DATABASE_SESSIONS),
      `    DECLARE @sql nvarchar(max) = N'DROP DATABASE ' + QUOTENAME(@database) + N';';`,
      `    EXEC (@sql);`,
      `    RETURN 1;`,
    ]),
    kill_connections: procedure("kill_connections", "@database nvarchar(128)", "Ends every other session in a slot database the pool login owns (a foreign session blocks a restore with 3101); returns how many.", [
      databaseCheck(),
      poolSid(),
      `    IF DB_ID(@database) IS NULL`,
      `    BEGIN`,
      `        THROW ${SQL_ERRORS.missing}, ${sqlString("arashouse_admin: the database does not exist")}, 1;`,
      `    END;`,
      ownerCheck(),
      `    DECLARE @killed int = 0;`,
      killSessions(DATABASE_SESSIONS),
      `    RETURN @killed;`,
    ]),
    create_slot_login: procedure(
      "create_slot_login",
      "@login nvarchar(128), @password nvarchar(128)",
      "Creates a slot's SQL login with this password (1), or sets the password of the existing one (0). The password is never returned or logged.",
      [
        loginCheck(),
        `    IF @password IS NULL OR LEN(@password) < 16`,
        `    BEGIN`,
        `        THROW ${SQL_ERRORS.badPassword}, ${sqlString("arashouse_admin: refused: a slot login's password must be at least 16 characters")}, 1;`,
        `    END;`,
        slotLoginCheck(),
        `    DECLARE @secret nvarchar(300) = N'N''' + REPLACE(@password, N'''', N'''''') + N'''';`,
        `    DECLARE @sql nvarchar(max);`,
        `    IF EXISTS (SELECT 1 FROM sys.server_principals WHERE name = @login)`,
        `    BEGIN`,
        `        SET @sql = N'ALTER LOGIN ' + QUOTENAME(@login) + N' WITH PASSWORD = ' + @secret;`,
        `        EXEC (@sql);`,
        `        SET @sql = N'ALTER LOGIN ' + QUOTENAME(@login) + N' ENABLE;';`,
        `        EXEC (@sql);`,
        `        RETURN 0;`,
        `    END;`,
        `    SET @sql = N'CREATE LOGIN ' + QUOTENAME(@login) + N' WITH PASSWORD = ' + @secret`,
        `        + N', DEFAULT_DATABASE = [master], CHECK_POLICY = OFF, CHECK_EXPIRATION = OFF;';`,
        `    EXEC (@sql);`,
        `    RETURN 1;`,
      ],
    ),
    drop_slot_login: procedure("drop_slot_login", "@login nvarchar(128)", "Ends a slot login's sessions and drops it (1), or does nothing when it does not exist (0).", [
      loginCheck(),
      `    IF NOT EXISTS (SELECT 1 FROM sys.server_principals WHERE name = @login) RETURN 0;`,
      slotLoginCheck(),
      `    DECLARE @killed int = 0;`,
      killSessions(LOGIN_SESSIONS),
      `    DECLARE @sql nvarchar(max) = N'DROP LOGIN ' + QUOTENAME(@login) + N';';`,
      `    EXEC (@sql);`,
      `    RETURN 1;`,
    ]),
    read_staged_backup: procedure(
      "read_staged_backup",
      "@file nvarchar(260)",
      "Verifies a backup a leaseholder staged and returns its header and file list (RESTORE HEADERONLY, FILELISTONLY: they need CREATE DATABASE, which the pool login has not).",
      [
        `    IF @file IS NULL`,
        `        OR DATALENGTH(@file) <> 2 * LEN(@file)`,
        `        OR NOT (@file COLLATE Latin1_General_BIN2 LIKE N'${stagedBackupPattern(vetted)}')`,
        `    BEGIN`,
        `        THROW ${SQL_ERRORS.refusedName}, ${sqlString(`arashouse_admin: refused: not a staged backup (${stagingDir("0".repeat(32), vetted).slice(0, -32)}<lease_id>\\${STAGED_BACKUP_NAME})`)}, 1;`,
        `    END;`,
        `    RESTORE VERIFYONLY FROM DISK = @file;`,
        `    RESTORE HEADERONLY FROM DISK = @file;`,
        `    RESTORE FILELISTONLY FROM DISK = @file;`,
      ],
    ),
    adopt_slot_database: procedure(
      "adopt_slot_database",
      "@database nvarchar(128)",
      "Makes the pool login the dbo inside a slot database it owns in sys.databases (a restored backup keeps its own dbo, and the pool login cannot open the database then); returns 1.",
      [
        databaseCheck(),
        poolSid(),
        `    IF DB_ID(@database) IS NULL`,
        `    BEGIN`,
        `        THROW ${SQL_ERRORS.missing}, ${sqlString("arashouse_admin: the database does not exist")}, 1;`,
        `    END;`,
        ownerCheck(),
        `    DECLARE @sql nvarchar(max) = N'ALTER AUTHORIZATION ON DATABASE::' + QUOTENAME(@database) + N' TO ' + QUOTENAME(${sqlString(POOL_LOGIN)}) + N';';`,
        `    EXEC (@sql);`,
        `    SET @sql = N'ALTER DATABASE ' + QUOTENAME(@database) + N' SET TRUSTWORTHY OFF; ALTER DATABASE ' + QUOTENAME(@database) + N' SET DB_CHAINING OFF;';`,
        `    EXEC (@sql);`,
        `    RETURN 1;`,
      ],
    ),
  };
}

// ---- what `arashouse doctor` says of the broker's SQL login -----------------------------------------

/**
 * The doctor's findings for SQL, from what the broker reads of its own login: it connects, it is in
 * neither `sysadmin` nor `dbcreator` (either could restore over any database on the server), and it
 * may execute every `arashouse_admin` procedure.
 */
export function checkSqlLogin(info: Pick<HostInfo, "sqlReachable" | "sqlLogin">): SetupFinding[] {
  const hint = "run `arashouse setup-sql` and the script it writes (docs/setup-sql.md)";
  if (!info.sqlReachable || info.sqlLogin === null) {
    return [{ level: "fail", check: "sql", message: `the broker cannot connect to SQL Server with its login; ${hint}` }];
  }
  const findings: SetupFinding[] = [{ level: "ok", check: "sql", message: "the broker's SQL login connects" }];
  const login = info.sqlLogin;
  if (login === undefined) {
    findings.push({ level: "warn", check: "sql login", message: "the broker does not report its SQL login's roles (it predates ticket 22); install this build with setup-host.ps1 -UpdateBroker (docs/setup.md)" });
    return findings;
  }
  const roles = [login.sysadmin ? "sysadmin" : "", login.dbcreator ? "dbcreator" : ""].filter(Boolean);
  const all = ADMIN_PROCEDURES.length;
  if (roles.length > 0) {
    findings.push({ level: "fail", check: "sql login", message: `${login.login} is in ${roles.join(" and ")}, so it could restore over any database on the server; take it out (docs/setup-sql.md)` });
  } else if (login.procedures < all) {
    findings.push({ level: "fail", check: "sql login", message: `${login.login} is neither sysadmin nor dbcreator, but executes ${login.procedures} of the ${all} ${UTILITY_DATABASE} procedures; ${hint}` });
  } else {
    findings.push({ level: "ok", check: "sql login", message: `${login.login} is neither sysadmin nor dbcreator, and executes the ${all} ${UTILITY_DATABASE} procedures` });
  }
  return findings;
}

// ---- the made-up names the negative test calls each procedure with -------------------------------

/**
 * Database names the procedures must refuse (50001). Each is made up: none is a database on the host,
 * and none is a name the tool would derive. The script also checks that none of them exists.
 */
export function negativeDatabaseNames(): string[] {
  const good = databaseName({ flavor: FLAVOR_KEYS[0] as SlotRef["flavor"], slot: 1 });
  return [
    "arashouse_madeup_01",
    good.replace(/_01$/, "_00"),
    good.replace(/_01$/, "_1"),
    good.replace(/_01$/, "_001"),
    good.toUpperCase(),
    `${good} `,
    ` ${good}`,
    `${good}'; SELECT 1; --`,
    `${good}]; SELECT 1; --`,
    `x${good}`,
    UTILITY_DATABASE,
    NEGATIVE_DATABASE,
    "",
  ];
}

/** Login names the procedures must refuse (50001), made up in the same way. */
export function negativeLoginNames(): string[] {
  const good = loginName({ flavor: FLAVOR_KEYS[0] as SlotRef["flavor"], slot: 1 }, "dbo");
  return [
    "arashouse_madeup_01_dbo",
    good.replace(/_01_/, "_00_"),
    good.replace(/_dbo$/, "_dbx"),
    good.replace(/_dbo$/, ""),
    good.toUpperCase(),
    `${good} `,
    `${good}'; SELECT 1; --`,
    POOL_USER,
    SIGNER,
    "",
  ];
}

/**
 * Paths `read_staged_backup` must refuse (50001), made up in the same way: none is a file the tool stages, so the
 * procedure refuses each before it reads anything.
 */
export function negativeStagedFiles(root: string = DEFAULT_INSTALL_ROOT): string[] {
  const hex = "0123456789abcdef".repeat(2);
  const good = stagedBackup(hex, root);
  const staging = stagingDir(hex, root).slice(0, -hex.length);
  return [
    `${staging}${hex}\\other.bak`,
    `${staging}${STAGED_BACKUP_NAME}`,
    `${staging}${hex.toUpperCase()}\\${STAGED_BACKUP_NAME}`,
    `${staging}${hex.slice(1)}\\${STAGED_BACKUP_NAME}`,
    `${staging}${hex}\\..\\${hex}\\${STAGED_BACKUP_NAME}`,
    `${staging}${hex}\\x\\${STAGED_BACKUP_NAME}`,
    `${root}\\golden\\${FLAVOR_KEYS[0]}\\db\\ootb.bak`,
    `C:\\other_root\\staging\\${hex}\\${STAGED_BACKUP_NAME}`,
    good.toUpperCase(),
    `${good} `,
    `${good}'; SELECT 1; --`,
    "",
  ];
}

// ---- the generated script ----------------------------------------------------------------------

export interface SetupSqlScriptOptions {
  /** The install root; `DEFAULT_INSTALL_ROOT` unless a test names another. Vetted by `assertValidRoot`. */
  readonly root?: string;
  /** The arashouse version that generated the script. */
  readonly version: string;
  /**
   * The SQL Server to connect to: the host's default instance by shared memory (`lpc:.`) unless a test
   * names a throw-away LocalDB instance of its own (`(localdb)\<name>`).
   */
  readonly dataSource?: string;
}

/** The host's default instance, by shared memory: TCP is off on the host (ticket 20). */
export const SQL_DATA_SOURCE = "lpc:.";

const DATA_SOURCE = /^(lpc:\.|\(localdb\)\\[A-Za-z0-9_]{1,64})$/;

const VERSION = /^[0-9A-Za-z.+-]{1,64}$/;

/** `<column> COLLATE Latin1_General_BIN2 LIKE N'<p1>' OR ...`: matches any of `patterns`, in a binary collation. */
export function likeAny(column: string, patterns: readonly string[]): string {
  return `(${patterns.map((p) => `${column} COLLATE Latin1_General_BIN2 LIKE N'${p}'`).join(" OR ")})`;
}

/** A PowerShell array of single-quoted strings. */
function psArray(items: readonly string[]): string {
  return `@(${items.map(psQuote).join(", ")})`;
}

/** The statements that run as the pool login: impersonate, run, revert. Only the script's own check connection runs these. */
function asPool(body: string): string {
  return [`EXECUTE AS LOGIN = ${sqlString(POOL_LOGIN)};`, body, `REVERT;`].join("\n");
}

/** One refused call: the procedure's error number, 0 when it did not refuse. */
function negativeCall(procedure: AdminProcedure): string {
  let args = procedure.endsWith("_login") ? "@login = @name" : procedure === "read_staged_backup" ? "@file = @name" : "@database = @name";
  if (procedure === "create_slot_login") args += ", @password = @password";
  return asPool(
    [
      `DECLARE @n int = 0;`,
      `BEGIN TRY`,
      `    EXEC ${UTILITY_DATABASE}.dbo.${procedure} ${args};`,
      `END TRY`,
      `BEGIN CATCH`,
      `    SET @n = ERROR_NUMBER();`,
      `END CATCH;`,
    ].join("\n"),
  ) + "\nSELECT @n;";
}

/**
 * The text of `setup-sql.ps1`. Every name and path in it comes from names.ts and this module; it changes
 * nothing without `-Apply`, touches only the objects named here, and lists no database but `arashouse_*`.
 */
export function renderSetupSqlScript(options: SetupSqlScriptOptions): string {
  if (!VERSION.test(options.version)) throw new Error("the version must be 1 to 64 letters, digits, '.', '+' or '-'");
  const root = assertValidRoot(options.root ?? DEFAULT_INSTALL_ROOT);
  if (root.includes("'")) throw new Error("the install root must not hold a quote");
  const dataSource = options.dataSource ?? SQL_DATA_SOURCE;
  if (!DATA_SOURCE.test(dataSource)) throw new Error(`the data source must be ${SQL_DATA_SOURCE} or a LocalDB instance, got "${dataSource}"`);
  const procedures = renderAdminProcedures(root);
  for (const text of Object.values(procedures)) {
    if (text.split("\n").some((l) => l.startsWith("'@"))) throw new Error("a procedure cannot sit in a here-string");
  }
  const adminFiles = databaseFiles(UTILITY_DATABASE, root);
  const selfTestDatabase = databaseName(SELF_TEST_SLOT);
  const selfTestLogin = loginName(SELF_TEST_SLOT, "dbo");
  const negativeBackup = `${stagingDir("arashouse-negative-madeup", root)}\\${NEGATIVE_DATABASE}.bak`;
  const procedureBlocks = ADMIN_PROCEDURES.map((name) => `$Procedures[${psQuote(name)}] = @'\n${procedures[name]}\n'@`).join("\n");
  const negativeCalls = ADMIN_PROCEDURES.map((name) => `$NegativeCall[${psQuote(name)}] = @'\n${negativeCall(name)}\n'@`).join("\n");
  const signers = SIGNERS.map((s) => `    ${psQuote(s.name)} = [ordered]@{ permissions = ${psArray(s.permissions)}; procedures = ${psArray(s.procedures)} }`).join("\n");
  const allPermissions = [...new Set(SIGNERS.flatMap((s) => s.permissions))];
  const poolHas = allPermissions.map((p) => `HAS_PERMS_BY_NAME(NULL, NULL, ${sqlString(p)})`).join(" + ");
  const poolExecutes = ADMIN_PROCEDURES.map((p) => `ISNULL(HAS_PERMS_BY_NAME(${sqlString(`${UTILITY_DATABASE}.dbo.${p}`)}, N'OBJECT', N'EXECUTE'), 0)`).join(" + ");

  return `# setup-sql.ps1: the one-time SQL Server preparation for arashouse (ticket 22), generated by \`arashouse setup-sql\` ${options.version}.
# Run it in Windows PowerShell 5.1 as a Windows user whose login is a SQL Server sysadmin (on this host the captain's own login;
# \`sa\` is not used). It connects to the default instance by shared memory with Windows authentication: no password is asked for,
# typed or stored. Without -Apply it prints what it would change (\`would do:\` lines) and changes nothing; with -Apply each change is
# printed (\`do:\`) and made. Then it checks the result as the broker's login, and prints \`result:\` and the result as JSON.
#
#   setup-sql.ps1                      the facts, the plan and the checks of what exists
#   setup-sql.ps1 -Apply               create or repair arashouse_admin, its procedures, their signature and the broker's login
#   setup-sql.ps1 -Apply -SelfTest     ... and, as the broker's login, create and drop the throw-away database ${selfTestDatabase}
#   setup-sql.ps1 -Uninstall [-Apply]  drop those objects again (ticket 49); refused while a slot's database or login is left
#
# It creates or changes only: the login [${POOL_LOGIN}] (no server role), the database ${UTILITY_DATABASE} (files under
# ${sqlDataDir(root)}\\), its user ${POOL_USER}, its seven procedures, the certificates ${SIGNERS.map((s) => s.name).join(" and ")} in
# ${UTILITY_DATABASE} and master, and the logins made from them. It lists only databases named arashouse_*, and never opens, backs up,
# restores or drops any other database. Idempotent: a second run changes only what differs.
# Exit codes: 0 ok, 1 a step or a check failed, 2 refused arguments, 3 cannot connect to SQL Server, 4 the login is not sysadmin.
param(
    [switch]$Apply,
    [switch]$SelfTest,
    [switch]$Uninstall
)
$ErrorActionPreference = 'Stop'

# ---- generated from src/core (names.ts, setup-sql.ts); do not edit ----
$ToolVersion = ${psQuote(options.version)}
$Root = ${psQuote(root)}
$SqlDataDir = ${psQuote(sqlDataDir(root))}
$AdminDatabase = ${psQuote(UTILITY_DATABASE)}
$AdminDataFile = ${psQuote(adminFiles.data)}
$AdminLogFile = ${psQuote(adminFiles.log)}
$PoolLogin = ${psQuote(POOL_LOGIN)}
$PoolUser = ${psQuote(POOL_USER)}
$Signers = [ordered]@{
${signers}
}
$ProcedureNames = ${psArray(ADMIN_PROCEDURES)}
$ProcedureSigner = @{}
foreach ($name in $Signers.Keys) { foreach ($p in $Signers[$name].procedures) { $ProcedureSigner[$p] = $name } }
$RefusedName = ${SQL_ERRORS.refusedName}
$NegativeDatabases = ${psArray(negativeDatabaseNames())}
$NegativeLogins = ${psArray(negativeLoginNames())}
$NegativeFiles = ${psArray(negativeStagedFiles(root))}
$NegativeDatabase = ${psQuote(NEGATIVE_DATABASE)}
$NegativeBackup = ${psQuote(negativeBackup)}
$SelfTestDatabase = ${psQuote(selfTestDatabase)}
$SelfTestLogin = ${psQuote(selfTestLogin)}
$SelfTestDataFile = ${psQuote(databaseFiles(selfTestDatabase, root).data)}
$SlotDatabaseFilter = ${psQuote(likeAny("name", databasePatterns()))}
$SlotLoginFilter = ${psQuote(likeAny("name", loginPatterns()))}
$ConnectionString = 'Data Source=${dataSource};Initial Catalog=master;Integrated Security=SSPI;Connect Timeout=10;Pooling=False;Application Name=arashouse-setup-sql'
$Procedures = [ordered]@{}
${procedureBlocks}
$NegativeCall = [ordered]@{}
${negativeCalls}
$PoolRolesQuery = @'
${asPool(`SELECT IS_SRVROLEMEMBER('sysadmin') AS sysadmin, IS_SRVROLEMEMBER('dbcreator') AS dbcreator, IS_SRVROLEMEMBER('securityadmin') AS securityadmin,
    ${poolHas} AS server_rights,
    HAS_PERMS_BY_NAME(NULL, NULL, N'CONTROL SERVER') AS control_server,
    ${poolExecutes} AS executes;`)}
'@
$DirectNegative = @'
${asPool(
  [
    `DECLARE @restore int = 0, @create int = 0;`,
    `BEGIN TRY`,
    `    RESTORE DATABASE ${sqlName(NEGATIVE_DATABASE)} FROM DISK = ${sqlString(negativeBackup)} WITH REPLACE;`,
    `END TRY`,
    `BEGIN CATCH`,
    `    SET @restore = ERROR_NUMBER();`,
    `END CATCH;`,
    `BEGIN TRY`,
    `    CREATE DATABASE ${sqlName(NEGATIVE_DATABASE)};`,
    `END TRY`,
    `BEGIN CATCH`,
    `    SET @create = ERROR_NUMBER();`,
    `END CATCH;`,
  ].join("\n"),
)}
SELECT @restore AS restore_error, @create AS create_error, CASE WHEN DB_ID(${sqlString(NEGATIVE_DATABASE)}) IS NULL THEN 0 ELSE 1 END AS exists_after;
'@
# ---- end of generated values ----

$Changes = New-Object System.Collections.ArrayList
$Planned = New-Object System.Collections.ArrayList
$Errors = New-Object System.Collections.ArrayList
$Conn = $null

function Fail([int]$Code, [string]$Message) {
    [Console]::Error.WriteLine("error: $Message")
    exit $Code
}

# Every change goes through here: without -Apply it is only printed.
function Invoke-Change([string]$Text, [scriptblock]$Action) {
    if (-not $Apply) {
        Write-Host "would do: $Text"
        [void]$Planned.Add($Text)
        return
    }
    Write-Host "do: $Text"
    & $Action
    [void]$Changes.Add($Text)
}

function New-Secret {
    # 32 random bytes as base64: the certificate's private-key password (dropped with the key) or a throw-away login's.
    $bytes = New-Object byte[] 32
    $rng = [Security.Cryptography.RandomNumberGenerator]::Create()
    try { $rng.GetBytes($bytes) } finally { $rng.Dispose() }
    return [Convert]::ToBase64String($bytes)
}

function Get-ErrorText($Err, [string[]]$Secrets = @()) {
    # The SqlException's number and message when there is one (PowerShell wraps it), with any secret of this run replaced.
    $e = $Err.Exception
    while ($e -and -not ($e -is [Data.SqlClient.SqlException])) { $e = $e.InnerException }
    $text = if ($e) { 'SQL error {0}: {1}' -f $e.Number, $e.Message } else { $Err.Exception.Message }
    foreach ($s in $Secrets) { if ($s) { $text = $text.Replace($s, '[redacted]') } }
    return $text
}

function Open-Sql([string]$Database = 'master') {
    $c = New-Object Data.SqlClient.SqlConnection $ConnectionString
    $c.Open()
    if ($Database -ne 'master') { $c.ChangeDatabase($Database) }
    return $c
}

function New-SqlCommand($Connection, [string]$Text, [hashtable]$Parameters) {
    $cmd = $Connection.CreateCommand()
    $cmd.CommandText = $Text
    $cmd.CommandTimeout = 120
    foreach ($k in $Parameters.Keys) {
        $p = $cmd.Parameters.Add('@' + $k, [Data.SqlDbType]::NVarChar, 4000)
        $p.Value = if ($null -eq $Parameters[$k]) { [DBNull]::Value } else { [string]$Parameters[$k] }
    }
    return $cmd
}

# The setup's own connection: every statement names its database first, so a change of database never carries over.
function Use-Database([string]$Database) { $script:Conn.ChangeDatabase($Database) }

function Invoke-Sql([string]$Database, [string]$Text, [hashtable]$Parameters = @{}) {
    # A failure names the statement's first line (statements carry a secret only as a parameter, never in their text).
    Use-Database $Database
    try { [void](New-SqlCommand $script:Conn $Text $Parameters).ExecuteNonQuery() }
    catch { throw ('{0} (in {1}: {2})' -f (Get-ErrorText $_), $Database, ($Text -split "\`n")[0].Trim()) }
}

function Get-SqlRows([string]$Database, [string]$Text, [hashtable]$Parameters = @{}, $Connection = $null) {
    if ($Connection) { $c = $Connection } else { Use-Database $Database; $c = $script:Conn }
    $reader = (New-SqlCommand $c $Text $Parameters).ExecuteReader()
    $rows = New-Object System.Collections.ArrayList
    try {
        while ($reader.Read()) {
            $row = [ordered]@{}
            for ($i = 0; $i -lt $reader.FieldCount; $i++) { $row[$reader.GetName($i)] = $(if ($reader.IsDBNull($i)) { $null } else { $reader.GetValue($i) }) }
            [void]$rows.Add($row)
        }
    } finally { $reader.Close() }
    return , @($rows)
}

function Get-SqlList([string]$Database, [string]$Text, [hashtable]$Parameters = @{}) {
    # The first column of every row (an empty array when there are none; piping rows through ForEach-Object would give @($null)).
    $out = New-Object System.Collections.ArrayList
    foreach ($row in (Get-SqlRows $Database $Text $Parameters)) { [void]$out.Add(@($row.Values)[0]) }
    return , @($out)
}

function Get-SqlValue([string]$Database, [string]$Text, [hashtable]$Parameters = @{}, $Connection = $null) {
    $rows = Get-SqlRows $Database $Text $Parameters $Connection
    if ($rows.Count -eq 0) { return $null }
    return @($rows[0].Values)[0]
}

function Normalize([string]$Text) { return ($Text -replace "\`r\`n", "\`n").Trim() }

# ---- reads ----

function Get-Facts {
    $f = (Get-SqlRows 'master' @'
SELECT CONVERT(nvarchar(128), SERVERPROPERTY('ProductVersion')) AS version,
    CONVERT(nvarchar(128), SERVERPROPERTY('ProductLevel')) AS level,
    CONVERT(nvarchar(128), SERVERPROPERTY('Edition')) AS edition,
    CONVERT(int, SERVERPROPERTY('IsIntegratedSecurityOnly')) AS windows_only,
    CONVERT(nvarchar(260), SERVERPROPERTY('InstanceDefaultDataPath')) AS data_path,
    SUSER_SNAME() AS connected_as,
    IS_SRVROLEMEMBER('sysadmin') AS sysadmin,
    (SELECT CONVERT(int, is_disabled) FROM sys.server_principals WHERE sid = 0x01) AS sid_one_disabled,
    (SELECT TOP (1) service_account FROM sys.dm_server_services WHERE servicename LIKE N'SQL Server (%') AS service_account
'@)[0]
    $dbs = (Get-SqlList 'master' "SELECT name FROM sys.databases WHERE name LIKE N'arashouse[_]%' ORDER BY name")
    return [ordered]@{
        version = $f.version; level = $f.level; edition = $f.edition
        authentication = $(if ($f.windows_only -eq 1) { 'windows only' } else { 'mixed (SQL logins work)' })
        saEnabled = $(if ($null -eq $f.sid_one_disabled) { $null } else { $f.sid_one_disabled -eq 0 })
        saUsed = $false
        serviceAccount = $f.service_account
        defaultDataPath = $f.data_path
        connectedAs = $f.connected_as
        sysadmin = ($f.sysadmin -eq 1)
        arashouseDatabases = $dbs
    }
}

function Get-State {
    $s = [ordered]@{}
    $login = (Get-SqlRows 'master' 'SELECT principal_id, type, CONVERT(int, is_disabled) AS disabled FROM sys.server_principals WHERE name = @login' @{ login = $PoolLogin })
    $s.poolLogin = [ordered]@{ exists = ($login.Count -gt 0); disabled = $null; roles = @(); serverPermissions = @(); ownsOther = 0 }
    if ($login.Count -gt 0) {
        $s.poolLogin.disabled = ($login[0].disabled -eq 1)
        $s.poolLogin.roles = (Get-SqlList 'master' 'SELECT r.name FROM sys.server_role_members m JOIN sys.server_principals r ON r.principal_id = m.role_principal_id WHERE m.member_principal_id = @id' @{ id = $login[0].principal_id })
        $s.poolLogin.serverPermissions = (Get-SqlList 'master' "SELECT permission_name FROM sys.server_permissions WHERE grantee_principal_id = @id AND state IN ('G', 'W') AND permission_name <> N'CONNECT SQL'" @{ id = $login[0].principal_id })
        $s.poolLogin.ownsOther = [int](Get-SqlValue 'master' "SELECT COUNT(*) FROM sys.databases WHERE owner_sid = SUSER_SID(@login) AND name NOT LIKE N'arashouse[_]%'" @{ login = $PoolLogin })
    }
    $db = Get-SqlRows 'master' 'SELECT CONVERT(int, is_trustworthy_on) AS trustworthy, CONVERT(int, is_db_chaining_on) AS chaining FROM sys.databases WHERE name = @db' @{ db = $AdminDatabase }
    $s.adminDatabase = [ordered]@{ exists = ($db.Count -gt 0); trustworthy = $null; chaining = $null }
    $s.poolUser = [ordered]@{ exists = $false; mapped = $false; roles = @(); extraPermissions = @() }
    $s.procedures = [ordered]@{ current = @(); stale = @(); unsigned = @(); extra = @(); notGranted = @() }
    $s.signers = [ordered]@{}
    foreach ($name in $Signers.Keys) { $s.signers[$name] = [ordered]@{ adminCertificate = $false; privateKeyRemoved = $false; masterCertificate = $false; sameThumbprint = $false; login = $false; permissions = @() } }
    if ($db.Count -gt 0) {
        $s.adminDatabase.trustworthy = ($db[0].trustworthy -eq 1)
        $s.adminDatabase.chaining = ($db[0].chaining -eq 1)
        $user = Get-SqlRows $AdminDatabase "SELECT principal_id, CASE WHEN sid = SUSER_SID(@login) THEN 1 ELSE 0 END AS mapped FROM sys.database_principals WHERE name = @user" @{ user = $PoolUser; login = $PoolLogin }
        if ($user.Count -gt 0) {
            $s.poolUser.exists = $true
            $s.poolUser.mapped = ($user[0].mapped -eq 1)
            $s.poolUser.roles = (Get-SqlList $AdminDatabase 'SELECT r.name FROM sys.database_role_members m JOIN sys.database_principals r ON r.principal_id = m.role_principal_id WHERE m.member_principal_id = @id' @{ id = $user[0].principal_id })
            $s.poolUser.extraPermissions = (Get-SqlList $AdminDatabase @'
SELECT p.permission_name + N' on ' + p.class_desc + ISNULL(N' ' + OBJECT_NAME(p.major_id), N'') COLLATE DATABASE_DEFAULT AS what
FROM sys.database_permissions p
WHERE p.grantee_principal_id = @id AND p.state IN ('G', 'W')
    AND NOT (p.class = 0 AND p.permission_name = N'CONNECT')
    AND NOT (p.class = 1 AND p.permission_name = N'EXECUTE' AND OBJECT_SCHEMA_NAME(p.major_id) = N'dbo' AND OBJECT_NAME(p.major_id) IN (SELECT value FROM STRING_SPLIT(@procs, N',')))
'@ @{ id = $user[0].principal_id; procs = ($ProcedureNames -join ',') })
            $granted = (Get-SqlList $AdminDatabase "SELECT OBJECT_NAME(major_id) AS name FROM sys.database_permissions WHERE grantee_principal_id = @id AND class = 1 AND permission_name = N'EXECUTE' AND state = 'G'" @{ id = $user[0].principal_id })
            $s.procedures.notGranted = @($ProcedureNames | Where-Object { $granted -notcontains $_ })
        } else { $s.procedures.notGranted = @($ProcedureNames) }
        $existing = Get-SqlRows $AdminDatabase @'
SELECT p.name, m.definition,
    (SELECT TOP (1) c.name FROM sys.crypt_properties cp JOIN sys.certificates c ON c.thumbprint = cp.thumbprint WHERE cp.major_id = p.object_id ORDER BY c.name) AS signer,
    (SELECT COUNT(*) FROM sys.crypt_properties cp WHERE cp.major_id = p.object_id) AS signatures
FROM sys.procedures p JOIN sys.sql_modules m ON m.object_id = p.object_id
'@
        foreach ($p in $existing) {
            if ($ProcedureNames -notcontains $p.name) { $s.procedures.extra += $p.name; continue }
            if ((Normalize $p.definition) -ne (Normalize $Procedures[$p.name])) { $s.procedures.stale += $p.name; continue }
            # Signed by its own certificate and by nothing else: no procedure may carry the other certificate's rights.
            if ($p.signatures -ne 1 -or $p.signer -ne $ProcedureSigner[$p.name]) { $s.procedures.unsigned += $p.name; continue }
            $s.procedures.current += $p.name
        }
        foreach ($name in $Signers.Keys) {
            $sig = $s.signers[$name]
            $cert = Get-SqlRows $AdminDatabase "SELECT CONVERT(nvarchar(100), thumbprint, 1) AS thumbprint, pvt_key_encryption_type AS key_type FROM sys.certificates WHERE name = @signer" @{ signer = $name }
            $masterCert = Get-SqlRows 'master' "SELECT CONVERT(nvarchar(100), thumbprint, 1) AS thumbprint FROM sys.certificates WHERE name = @signer" @{ signer = $name }
            $sig.adminCertificate = ($cert.Count -gt 0)
            $sig.privateKeyRemoved = ($cert.Count -gt 0) -and ($cert[0].key_type -eq 'NA')
            $sig.masterCertificate = ($masterCert.Count -gt 0)
            $sig.sameThumbprint = ($cert.Count -gt 0) -and ($masterCert.Count -gt 0) -and ($cert[0].thumbprint -eq $masterCert[0].thumbprint)
            $signerLogin = Get-SqlRows 'master' "SELECT p.principal_id FROM sys.server_principals p JOIN sys.certificates c ON c.sid = p.sid WHERE p.name = @signer AND p.type = 'C' AND c.name = @signer" @{ signer = $name }
            $sig.login = ($signerLogin.Count -gt 0)
            if ($signerLogin.Count -gt 0) {
                $sig.permissions = @((Get-SqlList 'master' "SELECT permission_name FROM sys.server_permissions WHERE grantee_principal_id = @id AND state = 'G' AND permission_name <> N'CONNECT SQL'" @{ id = $signerLogin[0].principal_id }) | Sort-Object)
            }
        }
    }
    return $s
}

function Test-SignerCurrent($State) {
    if ($State.procedures.current.Count -ne $ProcedureNames.Count -or $State.procedures.extra.Count -ne 0) { return $false }
    foreach ($name in $Signers.Keys) {
        $sig = $State.signers[$name]
        $want = @($Signers[$name].permissions | Sort-Object)
        if (-not ($sig.adminCertificate -and $sig.privateKeyRemoved -and $sig.masterCertificate -and $sig.sameThumbprint -and $sig.login -and
            (($sig.permissions -join ',') -eq ($want -join ',')))) { return $false }
    }
    return $true
}

# ---- changes ----

function New-PoolLogin {
    Invoke-Sql 'master' ('CREATE LOGIN {0} FROM WINDOWS WITH DEFAULT_DATABASE = [master];' -f (Get-SqlValue 'master' 'SELECT QUOTENAME(@login)' @{ login = $PoolLogin }))
}

function Enable-PoolLogin {
    Invoke-Sql 'master' ('ALTER LOGIN {0} ENABLE;' -f (Get-SqlValue 'master' 'SELECT QUOTENAME(@login)' @{ login = $PoolLogin }))
}

function New-AdminDatabase {
    Invoke-Sql 'master' ("CREATE DATABASE [{0}] ON PRIMARY (NAME = [{0}_data], FILENAME = N'{1}') LOG ON (NAME = [{0}_log], FILENAME = N'{2}');" -f $AdminDatabase, $AdminDataFile, $AdminLogFile)
    Invoke-Sql 'master' ('ALTER DATABASE [{0}] SET RECOVERY SIMPLE; ALTER DATABASE [{0}] SET AUTO_CLOSE OFF;' -f $AdminDatabase)
}

function Set-AdminDatabaseSafe {
    Invoke-Sql 'master' ('ALTER DATABASE [{0}] SET TRUSTWORTHY OFF; ALTER DATABASE [{0}] SET DB_CHAINING OFF;' -f $AdminDatabase)
}

function Set-PoolUser($State) {
    $login = Get-SqlValue 'master' 'SELECT QUOTENAME(@login)' @{ login = $PoolLogin }
    if ($State.poolUser.exists) { Invoke-Sql $AdminDatabase ('ALTER USER [{0}] WITH LOGIN = {1};' -f $PoolUser, $login) }
    else { Invoke-Sql $AdminDatabase ('CREATE USER [{0}] FOR LOGIN {1} WITH DEFAULT_SCHEMA = [dbo];' -f $PoolUser, $login) }
}

function Build-Procedures {
    # Drop the old procedures and certificates, then for each certificate: create its procedures, sign each with a new certificate,
    # grant the pool user EXECUTE, remove the private key (so nothing new can be signed), then copy the public certificate to master
    # and give its login the rights.
    foreach ($name in (Get-SqlList $AdminDatabase 'SELECT name FROM sys.procedures')) {
        Invoke-Sql $AdminDatabase ('DROP PROCEDURE [dbo].{0};' -f (Get-SqlValue $AdminDatabase 'SELECT QUOTENAME(@n)' @{ n = $name }))
    }
    foreach ($signer in $Signers.Keys) {
        Invoke-Sql 'master' ("IF SUSER_ID(N'{0}') IS NOT NULL DROP LOGIN [{0}]; IF CERT_ID(N'{0}') IS NOT NULL DROP CERTIFICATE [{0}];" -f $signer)
        Invoke-Sql $AdminDatabase ("IF CERT_ID(N'{0}') IS NOT NULL DROP CERTIFICATE [{0}];" -f $signer)
    }
    foreach ($signer in $Signers.Keys) {
        $secret = New-Secret
        try {
            Invoke-Sql $AdminDatabase ("DECLARE @sql nvarchar(max) = N'CREATE CERTIFICATE [{0}] ENCRYPTION BY PASSWORD = N''' + REPLACE(@secret, N'''', N'''''') + N''' WITH SUBJECT = N''arashouse_admin procedures (arashouse tickets 22 and 39)'', EXPIRY_DATE = ''20991231'';'; EXEC (@sql);" -f $signer) @{ secret = $secret }
            foreach ($name in $Signers[$signer].procedures) {
                Invoke-Sql $AdminDatabase $Procedures[$name]
                Invoke-Sql $AdminDatabase ("DECLARE @sql nvarchar(max) = N'ADD SIGNATURE TO [dbo].[{0}] BY CERTIFICATE [{1}] WITH PASSWORD = N''' + REPLACE(@secret, N'''', N'''''') + N''';'; EXEC (@sql);" -f $name, $signer) @{ secret = $secret }
                Invoke-Sql $AdminDatabase ('GRANT EXECUTE ON [dbo].[{0}] TO [{1}];' -f $name, $PoolUser)
            }
            Invoke-Sql $AdminDatabase ('ALTER CERTIFICATE [{0}] REMOVE PRIVATE KEY;' -f $signer)
        } catch {
            throw (Get-ErrorText $_ @($secret))
        } finally {
            $secret = $null
        }
        $public = [string](Get-SqlValue $AdminDatabase 'SELECT CONVERT(varchar(max), CERTENCODED(CERT_ID(@signer)), 1)' @{ signer = $signer })
        if ($public -notmatch '^0x[0-9A-Fa-f]+$') { throw "the signed certificate $signer could not be read back" }
        Invoke-Sql 'master' ('CREATE CERTIFICATE [{0}] FROM BINARY = {1};' -f $signer, $public)
        Invoke-Sql 'master' ('CREATE LOGIN [{0}] FROM CERTIFICATE [{0}];' -f $signer)
        foreach ($p in $Signers[$signer].permissions) { Invoke-Sql 'master' ('GRANT {0} TO [{1}];' -f $p, $signer) }
    }
}

function Grant-Procedures($Names) {
    foreach ($name in $Names) { Invoke-Sql $AdminDatabase ('GRANT EXECUTE ON [dbo].[{0}] TO [{1}];' -f $name, $PoolUser) }
}

# ---- checks, as the pool login (each on a connection of its own, closed afterwards) ----

function Test-PoolLogin {
    $c = Open-Sql
    try { $r = (Get-SqlRows 'master' $PoolRolesQuery @{} $c)[0] } finally { $c.Dispose() }
    $out = [ordered]@{
        sysadmin = ($r.sysadmin -eq 1); dbcreator = ($r.dbcreator -eq 1); securityadmin = ($r.securityadmin -eq 1)
        controlServer = ($r.control_server -eq 1); ownServerRights = [int]$r.server_rights; executes = [int]$r.executes
    }
    $out.ok = -not $out.sysadmin -and -not $out.dbcreator -and -not $out.securityadmin -and -not $out.controlServer -and $out.ownServerRights -eq 0 -and $out.executes -eq $ProcedureNames.Count
    return $out
}

function Test-Refusals {
    # Each procedure, called as the pool login with each made-up name, must refuse with the allowlist's error before doing anything.
    $password = New-Secret
    $results = New-Object System.Collections.ArrayList
    $c = Open-Sql
    try {
        foreach ($proc in $ProcedureNames) {
            $names = if ($proc.EndsWith('_login')) { $NegativeLogins } elseif ($proc -eq 'read_staged_backup') { $NegativeFiles } else { $NegativeDatabases }
            foreach ($name in $names) {
                $n = [int](Get-SqlValue 'master' $NegativeCall[$proc] @{ name = $name; password = $password } $c)
                [void]$results.Add([ordered]@{ procedure = $proc; name = $name; error = $n; ok = ($n -eq $RefusedName) })
            }
        }
        $direct = (Get-SqlRows 'master' $DirectNegative @{} $c)[0]
    } catch {
        throw (Get-ErrorText $_ @($password))
    } finally { $c.Dispose(); $password = $null }
    if ($direct.exists_after -ne 0) {
        # Only if the pool login could create it, which the check then fails on: the made-up name is this test's own.
        Invoke-Sql 'master' ('DROP DATABASE [{0}];' -f $NegativeDatabase)
    }
    # None of the made-up names may be a database here (compared exactly: binary, with trailing spaces).
    $madeUp = @($NegativeDatabases | Where-Object { $_ -ne $AdminDatabase }) -join '|'
    $madeUpPresent = [int](Get-SqlValue 'master' 'SELECT COUNT(*) FROM sys.databases d JOIN STRING_SPLIT(@names, N''|'') n ON d.name COLLATE Latin1_General_BIN2 = n.value COLLATE Latin1_General_BIN2 AND DATALENGTH(d.name) = DATALENGTH(n.value)' @{ names = $madeUp })
    $refused = @($results | Where-Object { $_.ok }).Count
    return [ordered]@{
        ok = ($refused -eq $results.Count) -and $direct.restore_error -ne 0 -and $direct.create_error -ne 0 -and $direct.exists_after -eq 0 -and $madeUpPresent -eq 0
        calls = $results.Count
        refused = $refused
        notRefused = @($results | Where-Object { -not $_.ok })
        directRestoreError = $direct.restore_error
        directCreateError = $direct.create_error
        madeUpDatabaseAfter = ($direct.exists_after -ne 0)
        madeUpNamesPresent = $madeUpPresent
    }
}

function Invoke-AsPool($Connection, [string]$Text, [hashtable]$Parameters = @{}) {
    $body = "EXECUTE AS LOGIN = N'{0}';\`nDECLARE @r int = NULL, @e int = 0, @m nvarchar(2048) = NULL;\`nBEGIN TRY\`n    {1}\`nEND TRY\`nBEGIN CATCH\`n    SET @e = ERROR_NUMBER(); SET @m = ERROR_MESSAGE();\`nEND CATCH;\`nREVERT;\`nSELECT @r AS result, @e AS error, @m AS message;" -f $PoolLogin.Replace("'", "''"), $Text
    return (Get-SqlRows 'master' $body $Parameters $Connection)[0]
}

function Test-RoundTrip {
    # As the pool login: create the throw-away slot database, create it again (a no-op), end a sysadmin session in it, create and drop a
    # slot login, drop the database. As this login in between: the owner and the data file. Leftovers are removed whatever happens.
    $out = [ordered]@{ ok = $false; steps = [ordered]@{}; error = $null }
    if ($null -ne (Get-SqlValue 'master' 'SELECT DB_ID(@db)' @{ db = $SelfTestDatabase }) -or $null -ne (Get-SqlValue 'master' 'SELECT SUSER_ID(@l)' @{ l = $SelfTestLogin })) {
        $out.error = "$SelfTestDatabase or $SelfTestLogin already exists; the self-test needs both absent and leaves them alone"
        return $out
    }
    $password = New-Secret
    $c = Open-Sql
    $victim = $null
    try {
        $step = { param($name, $sql, $params, $want)
            $r = Invoke-AsPool $c $sql $params
            $out.steps[$name] = [ordered]@{ result = $r.result; error = $r.error }
            if ($r.error -ne 0) { throw ('{0}: SQL error {1}: {2}' -f $name, $r.error, $r.message) }
            if ($null -ne $want -and $r.result -ne $want) { throw ('{0} returned {1}, not {2}' -f $name, $r.result, $want) }
        }
        & $step 'create' "EXEC @r = $AdminDatabase.dbo.create_slot_database @database = @db;" @{ db = $SelfTestDatabase } 1
        & $step 'create again' "EXEC @r = $AdminDatabase.dbo.create_slot_database @database = @db;" @{ db = $SelfTestDatabase } 0
        & $step 'adopt' "EXEC @r = $AdminDatabase.dbo.adopt_slot_database @database = @db;" @{ db = $SelfTestDatabase } 1
        $owner = Get-SqlValue 'master' 'SELECT SUSER_SNAME(owner_sid) FROM sys.databases WHERE name = @db' @{ db = $SelfTestDatabase }
        $file = Get-SqlValue 'master' "SELECT physical_name FROM sys.master_files WHERE database_id = DB_ID(@db) AND type = 0" @{ db = $SelfTestDatabase }
        $out.steps['owner'] = $owner
        $out.steps['data file'] = $file
        if ($owner -ne $PoolLogin) { throw "the new database's owner is $owner, not $PoolLogin" }
        if ($file -ne $SelfTestDataFile) { throw "the new database's data file is $file, not $SelfTestDataFile" }
        $victim = Open-Sql $SelfTestDatabase
        & $step 'kill a sysadmin session' "EXEC @r = $AdminDatabase.dbo.kill_connections @database = @db;" @{ db = $SelfTestDatabase } 1
        & $step 'create login' "EXEC @r = $AdminDatabase.dbo.create_slot_login @login = @l, @password = @p;" @{ l = $SelfTestLogin; p = $password } 1
        & $step 'set its password' "EXEC @r = $AdminDatabase.dbo.create_slot_login @login = @l, @password = @p;" @{ l = $SelfTestLogin; p = $password } 0
        & $step 'drop login' "EXEC @r = $AdminDatabase.dbo.drop_slot_login @login = @l;" @{ l = $SelfTestLogin } 1
        & $step 'drop' "EXEC @r = $AdminDatabase.dbo.drop_slot_database @database = @db;" @{ db = $SelfTestDatabase } 1
        & $step 'drop again' "EXEC @r = $AdminDatabase.dbo.drop_slot_database @database = @db;" @{ db = $SelfTestDatabase } 0
        $out.ok = $true
    } catch {
        $out.error = Get-ErrorText $_ @($password)
    } finally {
        if ($victim) { try { $victim.Dispose() } catch { } }
        try {
            # Only the two throw-away names, which were absent when the self-test began: each exists only if it created it.
            Invoke-Sql 'master' ("IF SUSER_ID(N'{0}') IS NOT NULL DROP LOGIN [{0}];" -f $SelfTestLogin)
            if ($null -ne (Get-SqlValue 'master' 'SELECT DB_ID(@db)' @{ db = $SelfTestDatabase })) {
                Invoke-Sql 'master' ('ALTER DATABASE [{0}] SET SINGLE_USER WITH ROLLBACK IMMEDIATE; DROP DATABASE [{0}];' -f $SelfTestDatabase)
                $out.error = "$($out.error) (the leftover $SelfTestDatabase was dropped)".Trim()
            }
        } catch { [void]$Errors.Add('self-test cleanup: ' + (Get-ErrorText $_)) }
        $c.Dispose()
        $password = $null
    }
    return $out
}

# ---- uninstall (ticket 49) ----

function Get-UninstallState {
    # What of this script's objects exists, and what would make dropping them unsafe: a slot's database or login (the pool login owns
    # each slot database; dropping it would orphan them), or any other database the pool login owns. Slot names are the pool's own.
    $s = [ordered]@{}
    $s.slotDatabases = (Get-SqlList 'master' ("SELECT name FROM sys.databases WHERE {0} ORDER BY name" -f $SlotDatabaseFilter))
    $s.slotLogins = (Get-SqlList 'master' ("SELECT name FROM sys.server_principals WHERE {0} ORDER BY name" -f $SlotLoginFilter))
    $s.poolLogin = ($null -ne (Get-SqlValue 'master' 'SELECT principal_id FROM sys.server_principals WHERE name = @login' @{ login = $PoolLogin }))
    $s.poolOwns = 0
    $s.poolSessions = 0
    if ($s.poolLogin) {
        $s.poolOwns = [int](Get-SqlValue 'master' 'SELECT COUNT(*) FROM sys.databases WHERE owner_sid = SUSER_SID(@login)' @{ login = $PoolLogin })
        $s.poolSessions = [int](Get-SqlValue 'master' 'SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE security_id = SUSER_SID(@login)' @{ login = $PoolLogin })
    }
    $s.adminDatabase = ($null -ne (Get-SqlValue 'master' 'SELECT DB_ID(@db)' @{ db = $AdminDatabase }))
    $s.adminDataFile = $null
    if ($s.adminDatabase) { $s.adminDataFile = Get-SqlValue 'master' 'SELECT physical_name FROM sys.master_files WHERE database_id = DB_ID(@db) AND type = 0' @{ db = $AdminDatabase } }
    $s.signerLogins = @($Signers.Keys | Where-Object { $null -ne (Get-SqlValue 'master' "SELECT principal_id FROM sys.server_principals WHERE name = @signer AND type = 'C'" @{ signer = $_ }) })
    $s.masterCertificates = @($Signers.Keys | Where-Object { $null -ne (Get-SqlValue 'master' 'SELECT CERT_ID(@signer)' @{ signer = $_ }) })
    return $s
}

function Remove-AdminDatabase {
    Invoke-Sql 'master' ('ALTER DATABASE [{0}] SET SINGLE_USER WITH ROLLBACK IMMEDIATE; DROP DATABASE [{0}];' -f $AdminDatabase)
}

function Remove-SignerLogin([string]$Name) { Invoke-Sql 'master' ('DROP LOGIN [{0}];' -f $Name) }

function Remove-MasterCertificate([string]$Name) { Invoke-Sql 'master' ('DROP CERTIFICATE [{0}];' -f $Name) }

function Remove-PoolLogin {
    # The broker may hold a session (each of its calls opens one); a login cannot be dropped while it is logged in.
    foreach ($spid in (Get-SqlList 'master' 'SELECT session_id FROM sys.dm_exec_sessions WHERE security_id = SUSER_SID(@login) AND session_id <> @@SPID' @{ login = $PoolLogin })) {
        Invoke-Sql 'master' ('KILL {0};' -f [int]$spid)
    }
    Invoke-Sql 'master' ('DROP LOGIN {0};' -f (Get-SqlValue 'master' 'SELECT QUOTENAME(@login)' @{ login = $PoolLogin }))
}

function Invoke-Uninstall {
    # Drops what -Apply created, in the reverse order, and nothing else: the utility database (and with it the pool user, the
    # procedures and their certificate), the certificate's login and its copy in master, then the broker's login. Refused, with
    # nothing changed, while a slot's database or login is left: \`arashouse teardown\` destroys the slots first.
    $state = Get-UninstallState
    $blocked = New-Object System.Collections.ArrayList
    if ($state.slotDatabases.Count -gt 0) { [void]$blocked.Add(('slot databases are left: {0}' -f ($state.slotDatabases -join ', '))) }
    if ($state.slotLogins.Count -gt 0) { [void]$blocked.Add(('slot logins are left: {0}' -f ($state.slotLogins -join ', '))) }
    if ($state.poolOwns -gt 0) { [void]$blocked.Add(('the login [{0}] owns {1} database(s)' -f $PoolLogin, $state.poolOwns)) }
    if ($state.adminDatabase -and $state.adminDataFile -ne $AdminDataFile) { [void]$blocked.Add(('{0} has its data file at {1}, not {2}: it is not the one this script made' -f $AdminDatabase, $state.adminDataFile, $AdminDataFile)) }
    if ($blocked.Count -gt 0) {
        foreach ($b in $blocked) { [void]$Errors.Add("refused: $b; destroy the slots first (arashouse teardown), nothing was dropped") }
        return $state
    }
    if ($state.adminDatabase) { Invoke-Change ("drop the database $AdminDatabase (its user $PoolUser, its procedures and the certificates {0} in it)" -f (@($Signers.Keys) -join ' and ')) { Remove-AdminDatabase } }
    foreach ($name in $state.signerLogins) { Invoke-Change "drop the login $name (made from the certificate)" { Remove-SignerLogin $name } }
    foreach ($name in $state.masterCertificates) { Invoke-Change "drop the certificate $name in master" { Remove-MasterCertificate $name } }
    if ($state.poolLogin) { Invoke-Change ("drop the login [{0}]{1}" -f $PoolLogin, $(if ($state.poolSessions -gt 0) { " after ending its $($state.poolSessions) session(s)" } else { '' })) { Remove-PoolLogin } }
    if ($Apply) { $state = Get-UninstallState }
    return $state
}

# ---- main ----

if ($Uninstall -and $SelfTest) { Fail 2 '-Uninstall takes only -Apply' }
if ($SelfTest -and -not $Apply) { Write-Host 'note: -SelfTest without -Apply checks the objects as they are now' }
try { $Conn = Open-Sql } catch { Fail 3 ('cannot connect to SQL Server by shared memory with Windows authentication: {0}' -f (Get-ErrorText $_)) }

$sysadmin = Get-SqlValue 'master' "SELECT CONCAT(SUSER_SNAME(), N'|', IS_SRVROLEMEMBER('sysadmin'))"
if (-not ([string]$sysadmin).EndsWith('|1')) { Fail 4 ('{0} is not a SQL Server sysadmin; run this as a Windows user whose login is' -f ([string]$sysadmin).Split('|')[0]) }
$facts = Get-Facts
Write-Host ('SQL Server {0} {1}, {2}; {3}; service account {4}; default data folder {5}' -f $facts.version, $facts.level, $facts.edition, $facts.authentication, $facts.serviceAccount, $facts.defaultDataPath)
Write-Host ('connected as {0} by Windows authentication (sysadmin: {1}); the sa login is {2} and is not used' -f $facts.connectedAs, $facts.sysadmin, $(if ($facts.saEnabled) { 'enabled' } elseif ($null -eq $facts.saEnabled) { 'not visible' } else { 'disabled' }))
Write-Host ('databases named arashouse_*: {0}' -f $(if ($facts.arashouseDatabases.Count -gt 0) { $facts.arashouseDatabases -join ', ' } else { 'none' }))

if ($Uninstall) {
    $state = $null
    try { $state = Invoke-Uninstall } catch { [void]$Errors.Add((Get-ErrorText $_)) }
    $gone = $state -and -not $state.adminDatabase -and $state.signerLogins.Count -eq 0 -and $state.masterCertificates.Count -eq 0 -and -not $state.poolLogin
    $ok = ($Errors.Count -eq 0) -and $(if ($Apply) { [bool]$gone } else { $true })
    $record = [ordered]@{
        schema = 1; tool = 'setup-sql.ps1'; version = $ToolVersion; time = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
        mode = 'uninstall'; applied = [bool]$Apply; ok = [bool]$ok; facts = $facts; state = $state
        changes = @($Changes); planned = @($Planned); errors = @($Errors)
    }
    $Conn.Dispose()
    Write-Host 'result:'
    Write-Host ($record | ConvertTo-Json -Depth 6)
    if (-not $ok) { exit 1 }
    exit 0
}

$state = $null
try {
    $state = Get-State
    if (-not $state.poolLogin.exists) { Invoke-Change "create the login [$PoolLogin] from Windows, in no server role" { New-PoolLogin } }
    elseif ($state.poolLogin.disabled) { Invoke-Change "enable the login [$PoolLogin]" { Enable-PoolLogin } }
    if ($state.poolLogin.roles.Count -gt 0) { [void]$Errors.Add(('the login [{0}] is a member of {1}: take it out by hand (it must hold no server role)' -f $PoolLogin, ($state.poolLogin.roles -join ', '))) }
    if ($state.poolLogin.serverPermissions.Count -gt 0) { [void]$Errors.Add(('the login [{0}] holds {1}: revoke it by hand' -f $PoolLogin, ($state.poolLogin.serverPermissions -join ', '))) }
    if ($state.poolLogin.ownsOther -gt 0) { [void]$Errors.Add(('the login [{0}] owns {1} database(s) not named arashouse_*' -f $PoolLogin, $state.poolLogin.ownsOther)) }

    if (-not $state.adminDatabase.exists) { Invoke-Change "create the database $AdminDatabase ($AdminDataFile, $AdminLogFile)" { New-AdminDatabase } }
    elseif ($state.adminDatabase.trustworthy -or $state.adminDatabase.chaining) { Invoke-Change "turn TRUSTWORTHY and DB_CHAINING off on $AdminDatabase" { Set-AdminDatabaseSafe } }

    if (-not $state.poolUser.exists -or -not $state.poolUser.mapped) { Invoke-Change "map the user $PoolUser in $AdminDatabase to [$PoolLogin]" { Set-PoolUser $state } }
    if ($state.poolUser.roles.Count -gt 0) { [void]$Errors.Add(('the user {0} is a member of {1} in {2}: take it out by hand' -f $PoolUser, ($state.poolUser.roles -join ', '), $AdminDatabase)) }
    if ($state.poolUser.extraPermissions.Count -gt 0) { [void]$Errors.Add(('the user {0} holds {1} in {2}: revoke it by hand' -f $PoolUser, ($state.poolUser.extraPermissions -join '; '), $AdminDatabase)) }

    if (-not (Test-SignerCurrent $state)) {
        $plan = @($Signers.Keys | ForEach-Object { '{0} signed with a new certificate {1} whose login gets {2}' -f ($Signers[$_].procedures -join ', '), $_, ($Signers[$_].permissions -join ', ') }) -join '; '
        Invoke-Change ('create the procedures and sign them, each certificate''s private key then removed: {0}; grant {1} EXECUTE on them' -f $plan, $PoolUser) { Build-Procedures }
    } elseif ($state.procedures.notGranted.Count -gt 0) {
        Invoke-Change ('grant {0} EXECUTE on {1}' -f $PoolUser, ($state.procedures.notGranted -join ', ')) { Grant-Procedures $state.procedures.notGranted }
    }
    if ($Apply) { $state = Get-State }
} catch {
    [void]$Errors.Add((Get-ErrorText $_))
}

$checks = [ordered]@{ poolLogin = $null; refusals = $null; selfTest = $null }
$inPlace = $state -and $state.poolLogin.exists -and $state.adminDatabase.exists -and $state.poolUser.mapped -and (Test-SignerCurrent $state)
if ($inPlace) {
    try {
        $checks.poolLogin = Test-PoolLogin
        Write-Host ('check: [{0}] sysadmin {1}, dbcreator {2}, securityadmin {3}, CONTROL SERVER {4}, own server rights {5}, executes {6} of {7} procedures' -f $PoolLogin,
            $checks.poolLogin.sysadmin, $checks.poolLogin.dbcreator, $checks.poolLogin.securityadmin, $checks.poolLogin.controlServer, $checks.poolLogin.ownServerRights, $checks.poolLogin.executes, $ProcedureNames.Count)
        if (-not $checks.poolLogin.ok) { [void]$Errors.Add("the login [$PoolLogin] holds a server role or right it must not, or cannot execute every procedure") }
        $checks.refusals = Test-Refusals
        Write-Host ('check: {0} of {1} calls with a made-up name refused ({2}); a direct RESTORE and CREATE DATABASE of {3} failed with {4} and {5}; it does not exist: {6}' -f
            $checks.refusals.refused, $checks.refusals.calls, $RefusedName, $NegativeDatabase, $checks.refusals.directRestoreError, $checks.refusals.directCreateError, (-not $checks.refusals.madeUpDatabaseAfter))
        if (-not $checks.refusals.ok) { [void]$Errors.Add('the negative test failed: a made-up name was not refused, or a direct restore or create was not') }
        if ($SelfTest) {
            $checks.selfTest = Test-RoundTrip
            Write-Host ('check: self-test round trip on {0}: {1}' -f $SelfTestDatabase, $(if ($checks.selfTest.ok) { 'ok' } else { $checks.selfTest.error }))
            if (-not $checks.selfTest.ok) { [void]$Errors.Add('the self-test failed: ' + $checks.selfTest.error) }
        }
    } catch {
        [void]$Errors.Add('check: ' + (Get-ErrorText $_))
    }
} elseif ($Apply) {
    [void]$Errors.Add('the objects are not all in place after -Apply')
} else {
    Write-Host 'check: skipped until the objects are in place (-Apply)'
}

$ok = ($Errors.Count -eq 0) -and $(if ($Apply) { [bool]$inPlace } else { $true })
$record = [ordered]@{
    schema = 1
    tool = 'setup-sql.ps1'
    version = $ToolVersion
    time = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
    mode = 'install'
    applied = [bool]$Apply
    ok = [bool]$ok
    facts = $facts
    state = $state
    checks = $checks
    changes = @($Changes)
    planned = @($Planned)
    errors = @($Errors)
}
if ($Conn) { $Conn.Dispose() }
Write-Host 'result:'
Write-Host ($record | ConvertTo-Json -Depth 6)
if (-not $ok) { exit 1 }
exit 0
`;
}
